static void measure_range(FAR const uint16_t *raw, int stride_pix,
                          int width, int height,
                          FAR uint16_t *black, FAR uint16_t *white)
{
  uint32_t hist[256];
  uint32_t total = 0;
  uint32_t acc;
  uint32_t lo;
  uint32_t hi;
  int x;
  int y;
  int i;

  memset(hist, 0, sizeof(hist));

  /* 隔行隔列采样就够定范围了，省一半时间 */

  for (y = 0; y < height; y += 2)
    {
      for (x = 0; x < width; x += 2)
        {
          hist[raw[y * stride_pix + x] >> 8]++;
          total++;
        }
    }

  if (total == 0)
    {
      *black = 0;
      *white = 0;
      return;
    }

  lo = total / 100;
  hi = total - lo;

  acc = 0;
  *black = 0;
  for (i = 0; i < 256; i++)
    {
      acc += hist[i];
      if (acc >= lo)
        {
          *black = (uint16_t)(i << 8);
          break;
        }
    }

  acc = 0;
  *white = 65535;
  for (i = 0; i < 256; i++)
    {
      acc += hist[i];
      if (acc >= hi)
        {
          *white = (uint16_t)(i << 8 | 0xff);
          break;
        }
    }

  if (*white <= *black)
    {
      *black = 0;
      *white = 0;                      /* 退回固定位移 */
    }
}

