          int cx = (x & 1) ^ (phase & 1);
          int cy = ((y - 1) & 1) ^ ((phase >> 1) & 1);
          int ch = (cy == 0 && cx == 0) ? 0 :
                   (cy == 1 && cx == 1) ? 2 : 1;
          uint16_t v = raw[(size_t)(y - 1) * stride_pix + x];

          if (v > black)
            {
              sum[ch] += (uint32_t)(v - black);
              cnt[ch]++;
