         *   Linux 的 dw_mmc 也是这么忽略的。判据要看 RESP0 的内容。
         */

        int try;
        uint32_t ocr = 0;

        for (try = 0; try < 20; try++)
          {
            dw_putreg(base, DWMMC_RINTSTS, DWMMC_INT_ALL);
            dw_putreg(base, DWMMC_CMDARG, ocr);
            dw_putreg(base, DWMMC_CMD,
