      msg[0].flags     = 0;
      msg[0].buffer    = &regaddr;
      msg[0].length    = 1;

      msg[1].frequency = 100000;
      msg[1].addr      = 0x10;
      msg[1].flags     = I2C_M_READ;
      msg[1].buffer    = &val;
      msg[1].length    = 1;

