{
  static const int16_t wave[48] =
  {
        0,  4276,  8480, 12539, 16383, 19947, 23169, 25995,
    28377, 30272, 31650, 32486, 32767, 32486, 31650, 30272,
    28377, 25995, 23169, 19947, 16383, 12539,  8480,  4276,
