   -28377,-25995,-23169,-19947,-16383,-12539, -8480, -4276
  };

  FAR int16_t *p = (FAR int16_t *)apb->samp;
  int n = nbytes / 2;
  int i;

  for (i = 0; i < n; i += 2)
    {
      int16_t v = wave[*phase];

      p[i]     = v;          /* 左 */
      p[i + 1] = v;          /* 右 */
      *phase   = (*phase + 1) % 48;
    }

  apb->nbytes  = nbytes;
