new = '''static int rk3576_wdt_stop(FAR struct watchdog_lowerhalf_s *lower)
{
  FAR struct rk3576_wdt_s *priv = (FAR struct rk3576_wdt_s *)lower;
  uint32_t before;
  uint32_t after;

  /* ★ DesignWare 看门狗的使能位是「写一次生效、软件清不掉」的 —— 但那
   *   说的是**这个模块自己的寄存器**。Rockchip 给每个外设都配了 CRU 软
   *   复位，复位整个 WDT 模块就能把 WDT_CR 连同使能位一起带回初值。
   *
   *   之前这里如实返回 -ENOSYS，理由是"IP 特性"。那个判断只查到了 IP
   *   手册这一层：**"这个寄存器位清不掉"和"这个模块停不下来"是两回事**，
   *   中间隔着 SoC 集成者提供的复位。
   *
   *   出处：rockchip,rk3576-cru.h
   *     SRST_P_WDT0 = 263 -> SOFTRST_CON(16) bit 7   （APB 寄存器域）
   *     SRST_T_WDT0 = 264 -> SOFTRST_CON(16) bit 8   （计数器 tclk 域）
   *   编号换算与 rk3576_reset() 一致，已由 SDIO 的 SRST_H_SDIO=684 在板上
   *   验证过。
   *
   *   复位后读回 WDT_CR 确认使能位真的没了 —— 停不下来却报告成功，代价是
   *   上层不再喂狗、板子过一会儿"莫名其妙重启"，极难追查。
   */

  UNUSED(priv);

  before = wdt_getreg(WDT_CR);

  rk3576_reset(WDT0_SRST_T, true);
  rk3576_reset(WDT0_SRST_P, true);
  up_udelay(10);
  rk3576_reset(WDT0_SRST_P, false);
  rk3576_reset(WDT0_SRST_T, false);
  up_udelay(10);

  after = wdt_getreg(WDT_CR);

  if ((after & WDT_CR_EN) != 0)
    {
      syslog(LOG_ERR,
             "WDT: 复位后使能位仍在 CR %08" PRIx32 " -> %08" PRIx32 "\\n",
             before, after);
      return -EIO;
    }

  syslog(LOG_INFO, "WDT: 已停（CR %08" PRIx32 " -> %08" PRIx32 "）\\n",
         before, after);
  return OK;
}

