  if (g_fbmem == NULL || area == NULL)
    {
      return -ENODEV;
    }

  start = (uintptr_t)g_fbmem + (uintptr_t)area->y * g_planeinfo.stride;
  end   = start + (uintptr_t)area->h * g_planeinfo.stride;

  if (end > (uintptr_t)g_fbmem + g_planeinfo.fblen)
    {
      end = (uintptr_t)g_fbmem + g_planeinfo.fblen;
    }

  up_flush_dcache(start, end);
  return OK;
}

