import serial, time, sys

s = serial.Serial('/dev/ttyUSB0', 1500000, timeout=0.05)

def wait_nsh(limit=90):
    buf=b''; t0=time.time()
    while time.time()-t0 < limit:
        s.write(b'\r\n'); time.sleep(0.35); buf+=s.read(65536)
        if b'nsh>' in buf[-300:]: return True
    return False

def run(cmd, secs):
    s.reset_input_buffer()
    for ch in cmd: s.write(ch.encode()); time.sleep(0.002)
    s.write(b'\r\n')
    b=b''; t=time.time(); poke=0
    while time.time()-t < secs:
        b+=s.read(65536)
        if time.time()-poke>0.4: poke=time.time(); s.write(b' ')
        time.sleep(0.03)
    return b.decode('utf-8','replace')

for step in range(4):
    if not wait_nsh():
        print("!! 第 %d 步：等不到 nsh" % step, flush=True); break
    time.sleep(12)          # 让 GMAC 后台线程刷完，别挤掉用例输出
    print("\n########## -r %d ##########" % step, flush=True)
    out = run("cmocka_driver_watchdog -r %d" % step, 45)
    print(out[-1500:], flush=True)
s.close()
