  vop_wr(VP1_INT_CLR, (VP1_INT_FS << 16) | VP1_INT_FS);
  printf("清除后(立即): STATUS=%08" PRIx32 " RAW=%08" PRIx32 "\n",
         vop_rd(VP1_INT_STATUS), vop_rd(VP1_INT_RAW));

