};

/*
 * ★ openvela 用的 I2C 总线，Linux 一条都不许碰。
 *
 *   内核带 CONFIG_I2C_RK3X=y，dtsi 里是 okay 的 I2C 控制器它全会接管
 *   （复位、改时钟分频、挂 adapter），不管下面有没有它认识的设备。
 *   2026-09-17 上板：同一份 openvela，单系统下 IMX415 正常出图，
 *   双系统下三个摄像头接口 I2C 全部无应答 → /dev/video0 注册失败 →
 *   界面点"打开相机"没反应。
 *
 *   划分见 amp/OWNERSHIP.md：
 *     i2c1  pmic@23（A72 调压）          → Linux，保留
 *     i2c2  hym8563 RTC、husb311         → openvela
 *     i2c3  es8388 音频                   → openvela
 *     i2c4 / i2c5 / i2c8  imx415         → openvela（摄像头整条链）
 *     i2c7  空                            → 关掉，免得 Linux 占着
 */

&i2c2 {
	status = "disabled";
};

&i2c3 {
	status = "disabled";
};

&i2c4 {
	status = "disabled";
};

&i2c5 {
	status = "disabled";
};

&i2c7 {
	status = "disabled";
};

&i2c8 {
	status = "disabled";
};

/*
 * ★ 摄像头的 AVDD 开关也得钉住。
 *
 *   这三个是 GPIO 控制的 regulator-fixed，消费者是 imx415 节点，而本内核
 *   没编 imx415 驱动 —— 在 Linux 眼里它们"没人用"，regulator 框架在
 *   late_initcall 会把它们关掉，sensor 当场掉电。道理和上面 vdd_cpu_lit_s0
 *   那条一样。
 */

&vcc_mipidcphy0 {
	regulator-always-on;
	regulator-boot-on;
};

&vcc_mipidphy1 {
	regulator-always-on;
	regulator-boot-on;
};

&vcc_mipidphy3 {
	regulator-always-on;
	regulator-boot-on;
};

