    }
#if !defined(CONFIG_ETH0_PHY_TJA1103)
  retries = 0;
  do
    {
      phydata = 0xffff;
#ifdef CONFIG_RK3576_ETH_PHY_MAE0621A
      {
        uint16_t oldpage = 0;
        rk3576_eth_readmii(priv, phyaddr, MAXIO_PAGE_SELECT, &oldpage);
        rk3576_eth_writemii(priv, phyaddr, MAXIO_PAGE_SELECT,
