    }
  else
    {
      nerr("ERROR: 速率未识别，自协商可能没完成: PHY STATUS=%04x\n",
           phydata);
      return -EIO;
    }
  putreg32(mac_conf | EMAC_MAC_CONFIGURATION_RE | EMAC_MAC_CONFIGURATION_TE,
