static void measure_awb(FAR const uint16_t *raw, int stride_pix,
                        int width, int height, int phase,
                        uint16_t black, FAR int *gain)
{
  uint64_t sum[3];
  uint32_t cnt[3];
  int x;
  int y;
  int i;
  memset(sum, 0, sizeof(sum));
  memset(cnt, 0, sizeof(cnt));
  gain[0] = gain[1] = gain[2] = AWB_UNITY;
