  for (y = 0; y + 1 < height; y += 4)
    {
      for (x = 0; x + 1 < width; x += 4)
        {
          int dx;
          int dy;
          for (dy = 0; dy < 2; dy++)
            {
              for (dx = 0; dx < 2; dx++)
                {
                  int px = x + dx;
                  int py = y + dy;
                  int cx = (px & 1) ^ (phase & 1);
                  int cy = (py & 1) ^ ((phase >> 1) & 1);
                  int ch = (cy == 0 && cx == 0) ? 0 :      /* R */
                           (cy == 1 && cx == 1) ? 2 : 1;   /* B : G */
                  uint16_t v = raw[(size_t)py * stride_pix + px];
                  if (v > black)
                    {
                      sum[ch] += (uint32_t)(v - black);
                      cnt[ch]++;
                    }
                }
            }
        }
    }
  if (cnt[0] == 0 || cnt[1] == 0 || cnt[2] == 0)
