      return;
    }
  {
    uint32_t mr = (uint32_t)(sum[0] / cnt[0]);
    uint32_t mg = (uint32_t)(sum[1] / cnt[1]);
    uint32_t mb = (uint32_t)(sum[2] / cnt[2]);
    if (mr == 0 || mb == 0)
      {
        return;
      }
    gain[0] = (int)(((uint64_t)mg * AWB_UNITY) / mr);
    gain[1] = AWB_UNITY;
    gain[2] = (int)(((uint64_t)mg * AWB_UNITY) / mb);
