static void agent_autostart(void)
{
  pthread_attr_t attr;
  pthread_t tid;

  pthread_attr_init(&attr);
  pthread_attr_setstacksize(&attr, 4096);
  if (pthread_create(&tid, &attr, agent_boot_thread, NULL) == 0)
    {
      pthread_detach(tid);
    }

  pthread_attr_destroy(&attr);
}

