/* 在每个 CPU 上各起一个绑核线程，看它能不能在 1 秒内跑起来。
 * 用来判断"就绪任务堆着、别的核却显示 IDLE"时，是哪个核不响应了。
 */

static volatile int g_cpu_ran[CONFIG_SMP_NCPUS];

static void *diag_cpu_thread(void *arg)
{
  g_cpu_ran[(intptr_t)arg] = sched_getcpu() + 1;
  return NULL;
}

static int diag_cpus(void)
{
  int i;

  for (i = 0; i < CONFIG_SMP_NCPUS; i++)
    {
      pthread_attr_t attr;
      pthread_t tid;
      cpu_set_t set;
      int ms;

      g_cpu_ran[i] = 0;
      CPU_ZERO(&set);
      CPU_SET(i, &set);
      pthread_attr_init(&attr);
      pthread_attr_setaffinity_np(&attr, sizeof(set), &set);
      if (pthread_create(&tid, &attr, diag_cpu_thread, (void *)(intptr_t)i) != 0)
        {
          printf("CPU%d: 建线程失败\\n", i);
          continue;
        }

      pthread_attr_destroy(&attr);
      for (ms = 0; ms < 1000 && g_cpu_ran[i] == 0; ms += 10)
        {
          usleep(10000);
        }

      if (g_cpu_ran[i] != 0)
        {
          printf("CPU%d: 响应（%d ms，实际在 CPU%d）\\n", i, ms,
